# -*- coding: utf-8 -*-
import requests

from hran_pacman.bases.wft_base import WFTDownloader
from hran_pacman.bases.logger import LOGGER
from hran_pacman.exceptions import InvalidVersionException, InvalidBuildException


class SBTSDownloader(WFTDownloader):
    technology = "SBTS"
    versions = []
    testpackages = []
    build_info_url_base = (
        'https://wft.int.net.nokia.com:8091/'
        'api/v1/SBTS/CI_ENB/builds/{baseline}.xml?'
        'items[]=storages&'
        'access_key=QF5oQmJRkaK4UWIDMGH0Ore6RcQMzseZ459IdCIB'
    )

    def __init__(self, baseline, version="A54", testpackage="", fsmr3=False, version_first=True, turbo_mode=False, strip_version=False):
        if version not in self.versions:
            raise InvalidVersionException(
                "Version {} is not a valid one. Available choices are: {}".format(version, ", ".join(self.versions))
            )

        if testpackage not in self.testpackages:
            raise InvalidVersionException(
                "Package version {} is not a valid one. Available choices are: {}".format(
                    testpackage, ", ".join(self.testpackages)
                )
            )

        self.version = version
        self.failover_version = 'A53' if self.version == 'A54' else 'A54'
        self.testpackage = testpackage
        self.fsmr3 = fsmr3
        self.version_first = version_first
        self.strip_version = strip_version
        self.package = None
        super(SBTSDownloader, self).__init__(baseline, turbo_mode)

    @property
    def package_name(self):
        return self.downloadable_name

    @property
    def downloaded_name(self):
        if self.strip_version:
            return self.package_name.replace("_" + self.version, "")
        return self.package_name

    def get_downloadable_file(self):
        try:
            self.package = super(SBTSDownloader, self).get_downloadable_file()
        except InvalidBuildException:
            LOGGER.info("Did not found downloadable file for name %s" % self.downloadable_name)
            self.version, self.failover_version = self.failover_version, self.version
            self.package = super(SBTSDownloader, self).get_downloadable_file()

    def get_software_package(self):
        """
        Method downloads software package to current working directory
        """
        data = requests.get(self.package.url, stream=True)
        self._stream_to_file(self.downloaded_name, data)

    def _download_package_to_temporary_container(self):
        self.get_downloadable_file()
        return super(WFTDownloader, self)._download_package_to_temporary_container()

    def _get_package_according_to_descision_tree(self):
        if self.package_is_available_locally():
            self.inform_that_package_is_available_locally()
            return True
        else:
            self.version, self.failover_version = self.failover_version, self.version
            if self.package_is_available_locally():
                self.inform_that_package_is_available_locally()
                return True
        self.version, self.failover_version = self.failover_version, self.version
        if self.package_is_available_remotely():
            self._get_package_from_remote()
            return True
        else:
            self.version, self.failover_version = self.failover_version, self.version
            if self.package_is_available_remotely():
                self._get_package_from_remote()
                return True
        self.version, self.failover_version = self.failover_version, self.version
        self.download_package_from_repository()

    def _get_package_from_remote(self):
        try:
            self.get_package_from_remote()
        except IOError as e:
            LOGGER.info('Package cannot be obtained from remote')
            LOGGER.debug('Exception has been triggered {}: {}'.format(e.__class__, e.__doc__))
            self.download_package_from_repository()


class SBTSPackageDownloader(SBTSDownloader):
    versions = ["A50", "A53", "A50E", "A53E", "CMCC_A50", "CMCC_A53", "A54", "A54E", "CMCC_A54"]
    testpackages = ["", "T1", "T2"]

    @property
    def downloadable_name(self):
        parts = self.baseline.split("_")
        parts.insert(2, self.version)
        return "{}{}.zip".format("_".join(parts), self.testpackage)

    def get_site_manager(self):
        """
        Implementation not needed - base class should probably be refactored
        """


class SBTS17PackageDownloader(SBTSDownloader):
    technology = "SBTS17"
    versions = ["A50", "A53", "A50E", "A53E", "CMCC_A50", "CMCC_A53", "A54", "A54E", "CMCC_A54"]
    testpackages = ["", "T1", "T2"]

    @property
    def downloadable_name(self):
        testpackage = ""
        hw = ""
        if self.testpackage:
            testpackage = "testpackage_{}".format(self.testpackage)
        if self.fsmr3:
            hw = "FSM-r3"
        if self.version_first:
            params = filter(None, [testpackage, self.version, hw])
        else:
            params = filter(None, [testpackage, hw, self.version])
        return "{}_release_BTSSM_downloadable_{}.zip".format(self.baseline, "_".join(params))

    def get_site_manager(self):
        """
        Currently same as in SBTSPackageDownloader...
        """


class SBTS18PackageDownloader(SBTSDownloader):
    technology = "SBTS18"
    versions = ["A50", "A53", "A50E", "A53E", "CMCC_A50", "CMCC_A53", "A54", "A54E", "CMCC_A54"]
    testpackages = ["", "T1", "T2"]

    @property
    def downloadable_name(self):
        testpackage = ""
        if self.testpackage:
            testpackage = "testpackage_{}_".format(self.testpackage)
        return "{}_release_BTSSM_downloadable_{}{}.zip".format(self.baseline, testpackage, self.version)

    def get_site_manager(self):
        """
        Currently same as in SBTSPackageDownloader...
        """
